"use client";

import { forwardRef, useId } from "react";
import { dashboardPageDefaults, type DashboardPageSpecProps } from "../generated/dashboard-page.types";
import { PageHeader } from "../page-header/page-header";
import { Stat } from "../stat/stat";
import { cx } from "../utils/cx";

export interface DashboardPageProps extends DashboardPageSpecProps {
  className?: string;
}

/**
 * One page of a dashboard: a title with its actions, a row of key numbers, then your content. It
 * sits inside DashboardShell but works anywhere. The title is the page's h1, so the page has one
 * clear heading to jump to.
 */
export const DashboardPage = forwardRef<HTMLDivElement, DashboardPageProps>(function DashboardPage(
  { title, description, actions, stats, isLoading = dashboardPageDefaults.isLoading, children, classNames, className },
  ref,
) {
  const statsId = useId();
  return (
    <div ref={ref} aria-busy={isLoading || undefined} className={cx("mx-auto flex w-full max-w-7xl min-w-0 flex-col gap-6 p-4 sm:p-6 lg:p-8", classNames?.root, className)}>
      <PageHeader
        title={title}
        description={description}
        actions={actions}
        classNames={{ root: classNames?.header, title: classNames?.title, description: classNames?.description, actions: classNames?.actions }}
      />

      {stats && stats.length > 0 && (
        <section aria-labelledby={statsId} className={classNames?.stats}>
          <h2 id={statsId} className="sr-only">
            Key numbers
          </h2>
          {/* As many columns as fit, each at least 10rem: four across on a wide page, two on a tablet or a phone. They follow the space the page has, not the screen. */}
          <div className="grid grid-cols-[repeat(auto-fit,minmax(min(10rem,100%),1fr))] gap-4">
            {stats.map((s) => (
              <Stat key={s.label} className={classNames?.stat} variant="card" label={s.label} value={s.value} trend={s.trend} data={s.data} description={s.description} summary={s.summary} isLoading={isLoading} />
            ))}
          </div>
        </section>
      )}

      {children && <div className={cx("flex min-w-0 flex-col gap-6", classNames?.content)}>{children}</div>}
    </div>
  );
});

/** One key number in the row at the top of a DashboardPage. The same fields as Stat. */
export interface DashboardStat {
  label: string;
  value: string | number;
  /** A signed percentage and what it is compared with, e.g. { change: 12, label: "vs last month" }. */
  trend?: { change: number; label?: string; goodWhen?: "up" | "down" };
  /** A short history, drawn as a small line under the number. */
  data?: number[];
  description?: string;
  /** A short headline in the card, e.g. "Trending up this month". */
  summary?: string;
}

// Generated by rdloom codegen from specs/dashboard-page.spec.json (v0.1.0).
// Do not edit. Change the spec and run `npm run gen`.

import type { ReactNode } from "react";

/** One page of a dashboard: a title with its actions, a row of key numbers, then your content. It sits inside DashboardShell but works anywhere. The title is the page's h1. */
export interface DashboardPageSpecProps {
  /**
   * The page's title, shown as its h1.
   */
  title: string;
  /**
   * One or two sentences under the title.
   */
  description?: string;
  /**
   * Buttons for the right of the title, e.g. Export and Add customer.
   */
  actions?: ReactNode;
  /**
   * The key numbers shown in a row of cards under the title: label, value, and optionally a trend, a small history and a note.
   */
  stats?: import("../dashboard-page/stats").DashboardStat[];
  /**
   * Show the key numbers as skeletons and mark the page busy.
   * @default false
   */
  isLoading?: boolean;
  /**
   * The rest of the page: charts, tables, forms.
   */
  children?: ReactNode;
  /**
   * Extra class names for single parts, so you can restyle one part without editing the file. Keys: root, header, title, description, actions, stats, stat, content.
   */
  classNames?: Partial<Record<"root" | "header" | "title" | "description" | "actions" | "stats" | "stat" | "content", string>>;
}

export const dashboardPageDefaults = {
  isLoading: false,
} as const;

export const dashboardPageMeta = {
  "name": "DashboardPage",
  "version": "0.1.0",
  "status": "experimental",
  "role": "none"
} as const;
